#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# What the human's clipboard holds, for the checks below.
clip_read() {
  if   command -v pbpaste     >/dev/null 2>&1; then pbpaste
  elif command -v wl-paste    >/dev/null 2>&1; then wl-paste
  elif command -v xclip       >/dev/null 2>&1; then xclip -selection clipboard -o
  elif command -v powershell.exe >/dev/null 2>&1; then
    powershell.exe -NoProfile -Command Get-Clipboard
  else return 1
  fi
}

# show_prefix TEXT: the first lines of a clipboard payload, indented.
show_prefix() {
  printf '%s\n' "$1" | head -n 3 | sed 's/^/        /'
}

# ask_yes_no "prompt" [previous]: asks until the answer is yes or no. Only the
# answer reaches stdout, so it can be captured in a command substitution. A
# closed stdin ends the wizard rather than looping on an unanswerable prompt.
ask_yes_no() {
  local prompt="$1" default="${2:-}" answer=""
  while true; do
    printf '  %s? %s%s ' "$YELLOW" "$prompt" "${default:+ [keep: $default]}" >&2
    if ! read -r answer; then
      printf '\n' >&2
      warn "no answer on stdin; stopping" >&2
      return 1
    fi
    [[ -z "$answer" ]] && answer="$default"
    case "$answer" in
      yes|no) printf '%s' "$answer"; return 0 ;;
    esac
    warn "answer yes or no" >&2
  done
}

# clip_write: replaces the clipboard with this script's stdin, so a payload left
# over from an earlier run cannot pass the checks below.
clip_write() {
  if   command -v pbcopy        >/dev/null 2>&1; then pbcopy
  elif command -v wl-copy       >/dev/null 2>&1; then wl-copy
  elif command -v xclip         >/dev/null 2>&1; then xclip -selection clipboard
  elif command -v powershell.exe >/dev/null 2>&1; then
    powershell.exe -NoProfile -Command 'Set-Clipboard -Value ""'
  else return 1
  fi
}

# clear_state: drops the answers recorded by an earlier run, so a re-run cannot
# report the last run's verdicts under a fresh report.
clear_state() {
  [[ -f "$ENV_FILE" ]] || return 0
  local tmp
  tmp=$(mktemp)
  grep -vE '^(HANDOFF_OK|PICKER_PAYLOAD_OK|PATCH_APPLIES|WHOLE_REPLY_OK|REFLOW|REFLOW_ACCEPTABLE)=' \
    "$ENV_FILE" > "$tmp" || true
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
}

# clip_into FILE: the clipboard payload, byte for byte, or an empty FILE.
clip_into() {
  clip_read > "$1" 2>/dev/null || : > "$1"
}

# ends_with_newline FILE: true when the last byte is a newline, which a patch needs.
# Counted with wc, not compared as text: command substitution strips the very
# newline being tested, so "$(tail -c1 "$f")" is empty for every file.
ends_with_newline() {
  [[ -s "$1" && "$(tail -c1 "$1" | wc -l | tr -d ' ')" -eq 1 ]]
}

run_wizard() {

TOTAL_STAGES=7

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TMP_ROOT="${TMPDIR:-/tmp}"
STATE="${PI_COPY_PASTE_VERIFY_STATE:-${TMP_ROOT%/}/pi-copy-paste-verify}"
SCRATCH="$STATE/repo"
ENV_FILE="$STATE/state.env"
REPORT="$REPO/docs/verification/live-$(date +%Y-%m-%d-%H%M%S).md"
mkdir -p "$STATE"

banner "Live verification: a hand-off block from reply to clipboard"

# A version string, or "not on PATH", so each tool is looked up once.
version_of() {
  local out
  if ! command -v "$1" >/dev/null 2>&1; then
    printf 'not on PATH'
    return
  fi
  out=$("$1" --version 2>/dev/null | head -n1 || true)
  [[ -z "$out" ]] && out="present"
  printf '%s' "$out"
}

stage "Preflight and the scratch repository"
say "The run happens in a scratch repo. Nothing under version control changes,"
say "apart from the report the last stage writes."
note "  scratch:    $SCRATCH"
note "  extension:  $REPO/src/index.ts"
if [[ -f "$REPO/src/index.ts" ]]; then
  note "✓ the extension under test is present"
else
  warn "$REPO/src/index.ts is missing; run this from a checkout of the package"
fi
PI_VERSION=$(version_of pi)
GIT_VERSION=$(version_of git)
NODE_VERSION=$(version_of node)
for bin in pi git node; do
  case "$bin" in
    pi) version=$PI_VERSION ;;
    git) version=$GIT_VERSION ;;
    node) version=$NODE_VERSION ;;
  esac
  note "$bin: $version"
  if [[ "$version" == "not on PATH" ]]; then
    warn "$bin is not on PATH; the stages that need it will not work"
  fi
done
# The payload stages read what the picker wrote through this shell's clipboard. When
# that is not the same clipboard pi writes to, the checks cannot run, and pretending
# otherwise is how an unread clipboard gets reported as a lost trailing newline.
if printf 'pi-copy-paste probe' | clip_write 2>/dev/null &&
  [[ "$(clip_read 2>/dev/null)" == 'pi-copy-paste probe' ]]; then
  CLIPBOARD_OK=yes
  note "✓ the clipboard round-trips through this shell"
else
  CLIPBOARD_OK=no
  warn "the clipboard does not come back through this shell"
  say "The picker's copy will still work; this shell just cannot see it. The payload"
  say "stages will record themselves as unchecked. Run the wizard from the same"
  say "terminal pi runs in, or paste each payload into an editor to check it by eye."
fi
# Always start from the seeded tree: a tree still carrying the last run's applied
# changes would let this run's checks pass without anything being pasted.
if [[ -d "$SCRATCH" ]]; then
  rm -rf "$SCRATCH"
  note "✓ cleared the previous scratch tree"
fi
mkdir -p "$SCRATCH/src"
git -C "$SCRATCH" init -q
cat > "$SCRATCH/src/greeting.ts" <<'TS'
export function greet(name: string): string {
  return `Hello, ${name}!`;
}
TS
git -C "$SCRATCH" add -A
git -C "$SCRATCH" -c user.email=verify@example.com -c user.name=verify \
  -c commit.gpgsign=false commit -qm "Seed the verification repo"
note "✓ seeded $SCRATCH/src/greeting.ts"
cat > "$STATE/prompt.txt" <<'TXT'
Rename the exported function greet to greeting in src/greeting.ts, and create
src/index.ts that re-exports greeting with an explicit return type. Hand both off
with copy_paste. Do not edit the files yourself.
TXT
note "the request to send is in $STATE/prompt.txt"
clear_state
pause

stage "Install it and hand off the change"
say "In a second terminal or pane, install the package into the scratch repo"
say "and start a real session on it. A fresh project asks for trust first; grant it,"
say "because nothing loads until it does:"
step "cd \"$SCRATCH\" && pi install --local \"$REPO\""
step "pi"
say "Then send the request in $STATE/prompt.txt (print it with: cat $STATE/prompt.txt):"
note "    Rename the exported function greet to greeting in src/greeting.ts, and"
note "    create src/index.ts that re-exports greeting with an explicit return type."
note "    Hand both off with copy_paste. Do not edit the files yourself."
say "The reply should end with a '## Hand-off' section holding two blocks:"
step "one for src/greeting.ts, fenced diff, caption 'N hunk'"
step "one for src/index.ts, fenced ts, caption 'new file, N lines'"
step "each block sits under one copy_paste tool call above the reply"
note "Leave pi running; the next stages use that session."
pause "Press Enter once the blocks are in the reply"
HANDOFF_OK=$(ask_yes_no "Were both blocks there, each from one copy_paste call?")
write_env HANDOFF_OK "$HANDOFF_OK"

stage "Pick the diff with the picker"
say "In the pi session, on that same reply:"
step "press Ctrl+Shift+C, or run /copy-paste"
step "the overlay should open on the Hand-off tab, its items labelled by caption"
step "choose the src/greeting.ts item and press enter"
step "press 2 for the Agent reply tab, check it lists the reply's own blocks, then 1"
step "watch for the 'Copied ...' notice"
printf '' | clip_write 2>/dev/null ||
  warn "could not clear the clipboard; an older payload could still pass the check"
pause "Press Enter once the block is on the clipboard"
clip_into "$STATE/picked.txt"
payload="$(cat "$STATE/picked.txt")"
if [[ -z "$payload" ]]; then
  # A copy that never reached this shell's clipboard is not the picker's fault, and
  # a human cannot certify bytes the script cannot see.
  PICKER_PAYLOAD_OK="unchecked: the clipboard read empty in this terminal"
  warn "the clipboard read empty here, so the payload could not be checked"
  say "Paste once into an editor to see what actually arrived. If the block is there,"
  say "this terminal's clipboard is not visible to the shell, which is a setup problem,"
  say "not a failure of the picker. Re-run from the terminal pi itself runs in."
elif [[ "$payload" == '```'* || "$payload" == '~~~'* ]]; then
  warn "the clipboard payload starts with a fence, not a patch header:"
  show_prefix "$payload"
  PICKER_PAYLOAD_OK="no: the payload carried its fence"
else
  show_prefix "$payload"
  case "$payload" in
    '--- a/src/greeting.ts'*)
      PICKER_PAYLOAD_OK=yes
      note "✓ bare patch: diff header and no fence, so nothing to strip by hand" ;;
    *)
      PICKER_PAYLOAD_OK="no: the payload does not start with --- a/src/greeting.ts"
      warn "the payload does not look like the block's body" ;;
  esac
fi
if [[ "$PICKER_PAYLOAD_OK" == yes ]]; then
  if ends_with_newline "$STATE/picked.txt"; then
    note "✓ the payload ends with a newline, so git will not call it corrupt"
  else
    PICKER_PAYLOAD_OK="no: the payload lost its trailing newline"
    warn "the payload does not end with a newline"
  fi
fi
write_env PICKER_PAYLOAD_OK "$PICKER_PAYLOAD_OK"

stage "Check the payload applies"
say "Applying is the applier's business and lives outside this package, so this stage"
say "only asks git whether the clipboard's patch fits the tree it was made against."
if [[ ! -s "$STATE/picked.txt" ]]; then
  PATCH_APPLIES="unchecked: nothing reached the clipboard to check"
  warn "skipped: the picker's payload never arrived, so there is nothing to hand to git"
elif git -C "$SCRATCH" apply --check -p1 "$STATE/picked.txt" 2>"$STATE/apply.err"; then
  PATCH_APPLIES=yes
  note "✓ git apply --check -p1 accepted the picked payload as it stands"
else
  PATCH_APPLIES="no: git apply --check refused the payload"
  warn "git refused the payload:"
  head -n 4 "$STATE/apply.err" | sed 's/^/        /'
fi
write_env PATCH_APPLIES "$PATCH_APPLIES"

stage "The whole-reply path"
say "Back in the pi session, on the same reply:"
step "press Ctrl+X (or run /copy) with nothing selected in fullscreen mode"
say "That copies the whole reply, fences and all. This stage checks that stripping the"
say "outer fence gives back exactly the patch the picker copied."
printf '' | clip_write 2>/dev/null ||
  warn "could not clear the clipboard; the reply check may read an older payload"
pause "Press Enter once the reply has been copied"
clip_into "$STATE/reply.txt"
reply="$(cat "$STATE/reply.txt")"
if [[ -n "$reply" ]]; then
  show_prefix "$reply"
fi
# The first fenced block after the heading, with its own fence lines removed.
awk '
  /^## Hand-off/ { section = 1; next }
  section && !opened && /^`{3,}/ { opened = 1; next }
  section && opened && /^`{3,}/ { exit }
  section && opened { print }
' "$STATE/reply.txt" > "$STATE/stripped.diff"
if [[ -z "$reply" ]]; then
  WHOLE_REPLY_OK="unchecked: the clipboard read empty in this terminal"
  warn "the clipboard read empty here, so the reply was never checked"
  say "Paste once to see whether the whole reply arrived; if it did, the clipboard is not"
  say "visible to this shell, and the copy itself is fine."
elif [[ ! -s "$STATE/stripped.diff" ]]; then
  WHOLE_REPLY_OK="no: no fenced block followed the Hand-off heading"
  warn "the clipboard held no fenced block to strip"
else
  # Command substitution drops the empty line the block leaves before its closing
  # fence and keeps one newline, which is the body byte for byte.
  printf '%s\n' "$(cat "$STATE/stripped.diff")" > "$STATE/stripped.normalized"
  if cmp -s "$STATE/stripped.normalized" "$STATE/picked.txt"; then
    WHOLE_REPLY_OK=yes
    note "✓ the stripped fence is the picker's payload, byte for byte"
  else
    WHOLE_REPLY_OK="no: the stripped fence differs from what the picker copied"
    warn "the stripped block is not the same text as the picked payload"
    diff "$STATE/picked.txt" "$STATE/stripped.normalized" | head -n 6 | sed 's/^/        /'
  fi
fi
write_env WHOLE_REPLY_OK "$WHOLE_REPLY_OK"

stage "Reflow"
say "The splice replaces the reply's text at the end of the turn, so watch the screen"
say "as the hand-off section appears: does the view jump, scroll, duplicate a block,"
say "or redraw half a screen?"
note "If you missed it, send another small change request and watch that turn."
ask REFLOW "One line on what you saw:"
REFLOW_ACCEPTABLE=$(ask_yes_no "Was the reflow acceptable?")
write_env REFLOW "$REFLOW"
write_env REFLOW_ACCEPTABLE "$REFLOW_ACCEPTABLE"

stage "Record the run"
say "Last thing, and nothing to type: the report goes to docs/verification/. Read it"
say "against docs/handoff-contract.md — a guarantee that did not hold, a caption that"
say "misled — and fix the contract rather than the code. Nothing here is gated on it."
mkdir -p "$REPO/docs/verification"
{
  printf '# Live verification: %s\n\n' "$(date +%Y-%m-%d)"
  printf 'A run of `scripts/verify-live.sh` against a scratch repository: the extension\n'
  printf 'installed in a real session, a block picked from the reply, and the clipboard payload\n'
  printf 'checked against git. Applying it is the applier\x27s business, and out of scope.\n\n'
  printf '| Criterion | Result |\n| --- | --- |\n'
  printf '| One `copy_paste` call hands off a change | %s |\n' "$HANDOFF_OK"
  printf '| The picker copies the body alone, no fence and a trailing newline | %s |\n' "$PICKER_PAYLOAD_OK"
  printf '| git apply --check accepts the picked payload | %s |\n' "$PATCH_APPLIES"
  printf '| The whole-reply path strips to the same patch | %s |\n' "$WHOLE_REPLY_OK"
  printf '| Reflow acceptable | %s |\n\n' "$REFLOW_ACCEPTABLE"
  printf '## Reflow\n\n%s\n\n' "$REFLOW"
  printf '## What the contract must change\n\nThis report is the record: read it against\n'
  printf '`docs/handoff-contract.md` and fix the contract where the run contradicted it.\n'
  printf 'Nothing in the table above is gated on that reading.\n\n'
  printf '## Environment\n\n'
  printf -- '- pi: %s\n' "$PI_VERSION"
  printf -- '- node: %s\n' "$NODE_VERSION"
  printf -- '- scratch repository: `%s`\n' "$SCRATCH"
  printf -- '- clipboard readable from the shell: %s\n' "$CLIPBOARD_OK"
} > "$REPORT"
note "✓ wrote $REPORT"
SKIPPED+=("read $REPORT (gitignored, so it is not committed)")
finish
printf '  %sReport: %s%s\n\n' "$GREEN" "$REPORT" "$RESET"
if [[ "$HANDOFF_OK" == yes && "$PICKER_PAYLOAD_OK" == yes &&
  "$PATCH_APPLIES" == yes && "$WHOLE_REPLY_OK" == yes ]]; then
  printf '  %s✓ every criterion passed%s\n\n' "$GREEN" "$RESET"
elif [[ "$PICKER_PAYLOAD_OK" == unchecked* || "$PATCH_APPLIES" == unchecked* ||
  "$WHOLE_REPLY_OK" == unchecked* ]]; then
  printf '  %s⚠ the payload could not be checked: this shell cannot see the clipboard%s\n\n' \
    "$YELLOW" "$RESET"
  exit 2
else
  printf '  %s⚠ the run did not pass; see the report%s\n\n' "$YELLOW" "$RESET"
  exit 1
fi
}

run_wizard "$@"; exit
